def build_state5():
    d = SLACK_D
    code = bytearray(); labels = {}; fix = []
    def emit(b): code.extend(b)
    def label(n): labels[n] = len(code)
    def jcc(op, n):  # near conditional/unconditional jump to local label or VA
        emit(op); fix.append((len(code), n)); emit(b'\0\0\0\0')
    def callva(va): emit(b'\xe8'); fix.append((len(code), va)); emit(b'\0\0\0\0')
    GV_INPUT, GV_MENU, GV_SND = 0xA75BC8, 0xA75DC8, 0xA7510C
    ld = lambda g: b'\x8b\x0d' + struct.pack('<I', g)          # mov ecx,[g]

    emit(b'\x8b\x4d\xfc')                                      # mov ecx,[ebp-4]
    emit(b'\x83\xb9\xf0\x00\x00\x00\x00')                  # cmp dword [ecx+0xf0],0
    jcc(b'\x0f\x8f', 'orig')                                   # jg orig (fade-in running)
    emit(ld(GV_INPUT)); callva(0x4689D0)                         # back pressed?
    emit(b'\x84\xc0'); jcc(b'\x0f\x85', 'back')
    emit(ld(GV_INPUT)); callva(0x468980)                         # confirm pressed?
    emit(b'\x84\xc0'); jcc(b'\x0f\x84', 'orig')
    emit(b'\x8b\x4d\xfc')                                      # mov ecx,[ebp-4]
    emit(b'\x8b\x81\xf8\x00\x00\x00')                       # mov eax,[ecx+0xf8]  focused control id
    emit(b'\x83\xf8\x30'); jcc(b'\x0f\x84', 'back')          # Sign Out -> back
    emit(b'\x83\xf8\x2e'); jcc(b'\x0f\x84', 'msg')
    emit(b'\x83\xf8\x2f'); jcc(b'\x0f\x84', 'msg')
    jcc(b'\xe9', 'orig')
    label('msg')
    emit(b'\x6a\x40')                                           # MB_ICONINFORMATION
    emit(b'\x68'); fix.append((len(code), 'cap')); emit(b'\0\0\0\0')
    emit(b'\x68'); fix.append((len(code), 'txt')); emit(b'\0\0\0\0')
    emit(b'\x6a\x00')
    callva(MSGBOX_THUNK)
    jcc(b'\xe9', STATE5_EXIT)
    label('back')
    emit(b'\x6a\x1e')                                           # push 0x1e
    emit(b'\x8b\x55\xfc')                                      # mov edx,[ebp-4]
    emit(b'\xff\x72\x2c')                                      # push [edx+0x2c]
    emit(ld(GV_MENU)); callva(0x6F2640)
    emit(b'\x8b\x4d\xfc')                                      # mov ecx,[ebp-4]
    emit(b'\xc7\x81\xf0\x00\x00\x00\x1e\x00\x00\x00')     # [ecx+0xf0]=0x1e
    emit(b'\xc7\x81\xf4\x00\x00\x00\x3c\x00\x00\x00')     # [ecx+0xf4]=0x3c
    emit(b'\xc7\x41\x10\x03\x00\x00\x00')                   # [ecx+0x10]=3 (main list state)
    emit(b'\x6a\x01\x6a\xff\x6a\x64')                         # push 1,-1,0x64
    emit(ld(GV_SND)); callva(0x48FD70)
    jcc(b'\xe9', STATE5_EXIT)
    label('orig')
    emit(b'\xc7\x45\xf0\x00\x00\x00\x00')                   # original instruction
    jcc(b'\xe9', STATE5_CONT)
    label('cap'); emit(b'KUF\0')
    label('txt'); emit(b'Lobby not built yet\0')
    assert len(code) <= 0x1E0 - 0x20, len(code)
    for pos, tgt in fix:
        if isinstance(tgt, str):
            target = d + labels[tgt]
            if tgt in ('cap', 'txt'):
                code[pos:pos+4] = struct.pack('<I', target); continue
        else:
            target = tgt
        code[pos:pos+4] = struct.pack('<i', target - (d + pos + 4))
    patches = [(d, b'\0' * len(code), bytes(code)),
               (STATE5_HOOK, b'\xc7\x45\xf0\x00\x00\x00\x00',
                b'\xe9' + rel(STATE5_HOOK + 5, d) + b'\x90\x90')]
    return patches

def build_state3_hook():
    e = 0x987D80; HOOK = 0x6A73B9
    code = bytearray(); fix = []; labels = {}
    def emit(b): code.extend(b)
    def jmpva(op, tgt): emit(op); fix.append((len(code), tgt)); emit(b'\0\0\0\0')
    def callva(va): emit(b'\xe8'); fix.append((len(code), va)); emit(b'\0\0\0\0')
    ld = lambda g: b'\x8b\x0d' + struct.pack('<I', g)
    emit(b'\xc7\x05' + struct.pack('<I', KUF_VA + 0xBF8) + b'\0\0\0\0')   # reset state-3 input guard
    emit(b'\x8b\x55\xfc')                          # mov edx,[ebp-4]
    emit(b'\x8b\x82\xf8\x00\x00\x00')           # mov eax,[edx+0xf8]  focused control
    emit(b'\x83\xf8\x24')                          # cmp eax,0x24  (Multi Game)
    jmpva(b'\x0f\x84', 'multi')
    emit(b'\x8b\x55\xfc')                          # original: mov edx,[ebp-4]
    emit(b'\x83\xba\xf8\x00\x00\x00\x23')      # original: cmp [edx+0xf8],0x23
    jmpva(b'\xe9', 0x6A73C3)                         # -> original jne
    labels['multi'] = len(code)
    emit(b'\x6a\x1e')
    emit(b'\x8b\x45\xfc'); emit(b'\xff\x70\x2c')   # push [eax+0x2c]
    emit(ld(0xA75DC8)); callva(0x6F2640)
    emit(b'\x8b\x55\xfc')
    emit(b'\xc7\x82\xf0\x00\x00\x00\x1e\x00\x00\x00')   # [edx+0xf0]=0x1e
    emit(b'\xc7\x82\xf4\x00\x00\x00\x3c\x00\x00\x00')   # [edx+0xf4]=0x3c
    emit(b'\xc7\x42\x10\x05\x00\x00\x00')                   # [edx+0x10]=5 (multiplayer state)
    emit(b'\x6a\x01\x6a\xff\x6a\x6d')
    emit(ld(0xA7510C)); callva(0x48FD70)
    jmpva(b'\xe9', 0x6A740E)
    for pos, tgt in fix:
        t = e + labels[tgt] if isinstance(tgt, str) else tgt
        code[pos:pos+4] = struct.pack('<i', t - (e + pos + 4))
    assert len(code) < 0x80
    return [(e, b'\0' * len(code), bytes(code)),
            (HOOK, b'\x8b\x55\xfc\x83\xba\xf8\x00\x00\x00\x23',
             b'\xe9' + rel(HOOK + 5, e) + b'\x90' * 5)]

def build_network_mode():
    """Stage 1 experiment: construct NetworkCmdManager in mode!=0 and let F8 force network mode."""
    patches = []
    # --- cave F (0x987D10): owner ctor, network branch ---
    f = 0x987D10; c = bytearray(); fix = []
    def emit(b): c.extend(b)
    def rj(op, tgt): emit(op); fix.append((len(c), tgt)); emit(b'\0\0\0\0')
    emit(b'\x83\x7d\x0c\x00')                   # cmp [ebp+0xc],0   (original)
    emit(b'\x75\x05')                              # jne net  (skip next jmp)
    rj(b'\xe9', 0x755776)                           # mode 0 -> original single-player path
    emit(b'\x68\x00\xe1\x00\x00')               # net: push 0xE100  (>= sizeof NetworkCmdManager)
    rj(b'\xe8', 0x8D5E88)                           # operator new
    emit(b'\x83\xc4\x04')                         # add esp,4
    emit(b'\x85\xc0')                              # test eax,eax
    emit(b'\x74\x07')                              # jz store (null stays null)
    emit(b'\x8b\xc8')                              # mov ecx,eax
    rj(b'\xe8', 0x7552D0)                           # NetworkCmdManager::ctor (returns this)
    emit(b'\x8b\x55\xf0')                         # store: mov edx,[ebp-0x10]
    emit(b'\x89\x42\x08')                         # mov [edx+8],eax
    rj(b'\xe9', 0x7557BD)
    for pos, tgt in fix: c[pos:pos+4] = struct.pack('<i', tgt - (f + pos + 4))
    assert len(c) <= 0x30, len(c)
    patches.append((f, b'\0' * len(c), bytes(c)))
    patches.append((0x755770, b'\x83\x7d\x0c\x00\x75\x47', b'\xe9' + rel(0x755775, f) + b'\x90'))
    # --- cave G (0x987D40): hold F8 when battle setup starts -> network mode flag ---
    g = 0x987D40; c = bytearray(); fix = []
    emit(b'')
    c += b'\x89\x8d\xf8\xfe\xff\xff'               # original: mov [ebp-0x108],ecx
    c += b'\x6a\x77'                                # push VK_F8
    c += b'\xff\x15' + struct.pack('<I', 0x988404)  # call [GetAsyncKeyState]
    c += b'\x66\xa9\x00\x80'                       # test ax,0x8000
    c += b'\x74\x0a'                                # jz skip
    c += b'\x8b\x85\xf8\xfe\xff\xff'               # mov eax,[ebp-0x108]
    c += b'\xc6\x40\x52\x01'                       # mov byte [eax+0x52],1
    c += b'\x6a\x01'                                # skip: original push 1
    c += b'\xe9' + struct.pack('<i', 0x69B3AB - (g + len(c) + 5))
    assert len(c) <= 0x40, len(c)
    patches.append((g, b'\0' * len(c), bytes(c)))
    patches.append((0x69B3A3, b'\x89\x8d\xf8\xfe\xff\xff\x6a\x01', b'\xe9' + rel(0x69B3A8, g) + b'\x90\x90\x90'))
    return patches


def add_section(data):
    """Append a new executable section (.kuf) holding the lobby code."""
    pe = struct.unpack_from('<I', data, 0x3c)[0]
    nsec = struct.unpack_from('<H', data, pe + 6)[0]
    optsz = struct.unpack_from('<H', data, pe + 20)[0]
    sect = pe + 24 + optsz
    if nsec != 6 or bytes(data[sect:sect + 5]) != b'.text':
        sys.exit('Unexpected section layout; aborting.')
    last = sect + 40 * (nsec - 1)
    lvs, lva, lrs, lrp = struct.unpack_from('<IIII', data, last + 8)
    if bytes(data[last:last + 6]) != b'.reloc':
        sys.exit('Unexpected last section; aborting.')
    new_va = (lva + lvs + 0xFFF) & ~0xFFF
    if new_va + 0x400000 != KUF_VA:
        sys.exit('Section address mismatch; aborting.')
    raw_off = (len(data) + 0x1FF) & ~0x1FF      # after any trailing data (kept intact)
    data.extend(b'\0' * (raw_off - len(data)))
    import keaton_fixes
    ko = keaton_fixes.KFIX_VA - 0x400000 - new_va
    assert len(KUF_BLOB) <= ko and ko + len(keaton_fixes.KFIX_BLOB) <= 0x20000, 'kfix area'
    blob = KUF_BLOB + b'\0' * (ko - len(KUF_BLOB)) + keaton_fixes.KFIX_BLOB
    raw_size = (len(blob) + 0x1FF) & ~0x1FF
    hdr = sect + 40 * nsec
    if any(data[hdr:hdr + 40]):
        sys.exit('No room for a section header; aborting.')
    struct.pack_into('<8sIIIIIIHHI', data, hdr, b'.kuf', 0x20000, new_va, raw_size, raw_off, 0, 0, 0, 0, 0xE0000060)
    struct.pack_into('<H', data, pe + 6, nsec + 1)
    soi = pe + 24 + 56
    struct.pack_into('<I', data, soi, new_va + 0x20000)
    data.extend(blob + b'\0' * (raw_size - len(blob)))
    # v42: .kfx = Keaton's Community Patch runtime routines (moved from her DLL, with permission)
    kva = keaton_fixes.KFX_VA - 0x400000
    assert kva == new_va + 0x20000, 'kfx address'
    kblob = keaton_fixes.KFX_BLOB
    kvs = (len(kblob) + 0xFFF) & ~0xFFF
    kraw = (len(kblob) + 0x1FF) & ~0x1FF
    koff = len(data)
    hdr2 = hdr + 40
    if any(data[hdr2:hdr2 + 40]) or hdr2 + 40 > struct.unpack_from('<I', data, pe + 24 + 60)[0]:
        sys.exit('No room for a second section header; aborting.')
    struct.pack_into('<8sIIIIIIHHI', data, hdr2, b'.kfx', kvs, kva, kraw, koff, 0, 0, 0, 0, 0xE0000060)
    struct.pack_into('<H', data, pe + 6, nsec + 2)
    struct.pack_into('<I', data, soi, kva + kvs)
    data.extend(kblob + b'\0' * (kraw - len(kblob)))
    # v93: .kjb = custom job data (icon DXT5 blocks) and the net module's zero-initialised data
    jva = KJB_VA - 0x400000
    assert jva == kva + kvs, 'kjb address'
    jraw = (len(JOB_BLOB) + 0x1FF) & ~0x1FF
    joff = len(data)
    hdr3 = hdr2 + 40
    if any(data[hdr3:hdr3 + 40]) or hdr3 + 40 > struct.unpack_from('<I', data, pe + 24 + 60)[0]:
        sys.exit('No room for a third section header; aborting.')
    struct.pack_into('<8sIIIIIIHHI', data, hdr3, b'.kjb', 0x30000, jva, jraw, joff, 0, 0, 0, 0, 0xE0000060)
    struct.pack_into('<H', data, pe + 6, nsec + 3)
    struct.pack_into('<I', data, soi, jva + 0x30000)   # TEST23: .kjb 0x28000 (overflow code + strings up to 0xB3B000); 2026-11-26: 0x30000 (up to 0xB43000, E build full)
    data.extend(JOB_BLOB + b'\0' * (jraw - len(JOB_BLOB)))

def main():
    if len(sys.argv) != 3:
        sys.exit(__doc__)
    data = bytearray(open(sys.argv[1], 'rb').read())
    import os; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import keaton_fixes
    plist = list(build())
    used = [(va, va + len(o)) for va, o, n in plist]
    for fx, va, o, n in keaton_fixes.PATCHES:      # v42: Keaton's Community Patch fixes (with permission)
        if any(a < va + len(o) and va < b for a, b in used):
            sys.exit(f'Keaton fix {fx} at {va:#x} overlaps an existing patch; aborting.')
        plist.append((va, o, n))
    for va, old, new in plist:
        o = off(va)
        if bytes(data[o:o + len(old)]) != old:
            sys.exit(f'Unexpected bytes at {va:#x}; wrong Heroes.exe build? Aborting.')
        data[o:o + len(new)] = new
    add_section(data)
    dc = struct.unpack_from('<H', data, DLLCHAR_OFF)[0]
    if not dc & 0x40 and dc != 0x8100:
        sys.exit('Unexpected DllCharacteristics; aborting.')
    struct.pack_into('<H', data, DLLCHAR_OFF, dc & ~0x40)      # clear DYNAMIC_BASE
    ch = struct.unpack_from('<H', data, 0x150 + 22)[0]
    struct.pack_into('<H', data, 0x150 + 22, ch | 0x20)        # v36: LARGE_ADDRESS_AWARE (4 GB on 64-bit Windows)
    open(sys.argv[2], 'wb').write(data)
    print('Wrote', sys.argv[2])

if __name__ == '__main__':
    main()
